function cartOptionField(item,p){const rows=productOptions(p);if(!rows.length)return '';return `<label class="cart-option">${safe(optionLabel(p))}<select data-cart-option="${safe(p.id)}" data-old-variant="${safe(item.variant||'')}" aria-label="${safe(optionLabel(p)+' — '+pname(p))}"><option value="">اختاري ${safe(optionLabel(p))}</option>${rows.map(x=>`<option value="${safe(x.id)}" ${item.variant===x.id?'selected':''}>${safe(x.label)}</option>`).join('')}</select></label>`}
function updateCartOption(id,oldVariant,newVariant){const p=find(id),item=state.cart.find(x=>x.id===id&&(x.variant||'')===oldVariant);if(!p||!item||!selectedOption(p,newVariant))return;const other=state.cart.find(x=>x!==item&&x.id===id&&x.variant===newVariant);if(other){other.qty+=item.qty;state.cart=state.cart.filter(x=>x!==item)}else item.variant=newVariant;state.selectedOptions[id]=newVariant;saveCart();refreshCartViews()}
function publicImageNote(p){const note=info(p).imageNote||'';return /الذكاء|الاصطناع|\bAI\b/i.test(note)?'':note}

try {const data=JSON.parse(localStorage.getItem(cartKey)||'[]');state.cart=Array.isArray(data)?data.filter(x=>x&&/^TS[A-Z0-9-]{4,64}$/.test(x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<11):[];}catch{}
