function renderDrawer(menu=false){dismissAssist();const el=$('#drawer');el.hidden=false;$('#cartAssist').hidden=true;$('#overlay').hidden=false;document.body.style.overflow='hidden';if(menu){el.innerHTML=`<div class="drawer-head"><h2>اكتشفي Trend Shop</h2><button class="drawer-close" data-close aria-label="إغلاق القائمة">×</button></div><div class="menu-list"><a href="#/">الرئيسية</a><a href="#/shop">جميع المنتجات</a><a href="#/offers">العروض والكومبوهات</a><a href="#/shop?new=1">وصل حديثًا</a><a href="#/shop?type=mascara">المسكارا</a>${categories.map(c=>`<a href="#/shop?cat=${encodeURIComponent(c[0])}">${c[2]}</a>`).join('')}<a href="#/privacy">الخصوصية</a>${$('.footer .brand-socials')?.outerHTML||''}</div>`;return}const items=cartItems();el.innerHTML=`<div class="drawer-head"><h2>سلتكِ الجميلة (${items.reduce((n,x)=>n+x.qty,0)})</h2><button class="drawer-close" data-close aria-label="إغلاق السلة">×</button></div>${items.length?items.map(item=>{const {id,qty,p,variant=''}=item,label=choiceName(p,variant),suffix=label?'، '+label:'';return `<div class="cart-line"><a href="#/product/${id}"><img src="${safe(thumb(p))}" alt="${safe(pname(p))}" loading="lazy"/></a><div><strong dir="auto">${safe(pname(p))}</strong><small>${money(pprice(p))}</small>${cartOptionField(item,p)}<div class="qty-row"><button data-qty="${id}" data-variant="${safe(variant)}" data-step="1" aria-label="زيادة كمية ${safe(pname(p)+suffix)}">+</button><span>${qty}</span><button data-qty="${id}" data-variant="${safe(variant)}" data-step="-1" aria-label="تقليل كمية ${safe(pname(p)+suffix)}">−</button></div></div><b>${money(pprice(p)*qty)}</b></div>`}).join('')+totalsMarkup(cartQuote())+`<a class="btn" href="#/checkout" style="width:100%">إتمام الطلب</a>`+cartIncentives():'<div class="empty"><span class="empty-icon">♡</span><p>سلتكِ بانتظار اختياراتكِ!</p><a class="btn btn-light" href="#/shop">ابدئي التسوق</a></div>'}`}
function totalsMarkup(q){return `<div class="cart-totals"><div class="summary-row"><span>مجموع المنتجات</span><b>${money(q.itemsSubtotalFils)}</b></div>${q.discountFils?`<div class="summary-row combo-saving"><span>خصم ${safe(q.promotions[0].title)}</span><b>− ${money(q.discountFils)}</b></div>`:''}<div class="summary-row"><span>التوصيل لكل الأردن</span><b>${q.shippingFeeFils===0?'مجاني':money(q.shippingFeeFils)}</b></div><div class="summary-row total"><strong>الإجمالي شامل التوصيل</strong><b>${money(q.totalFils)}</b></div></div>`}
function suggestionCards(anchorId,goal=false){const list=recommendations(state.products,state.cart,{anchorId,promotions:state.promotions,deliveryGoal:goal,limit:3});return list.length?`<div class="cart-recommendations">${list.map(({product:p,unlocksFreeDelivery})=>`<article class="cart-recommendation"><a href="#/product/${p.id}"><img src="${safe(thumb(p))}" alt="${safe(pname(p))}" loading="lazy" width="64" height="70"/></a><div><a href="#/product/${p.id}">${safe(pname(p))}</a><b>${money(pprice(p))}</b>${unlocksFreeDelivery?'<small>إضافته تمنحكِ التوصيل المجاني</small>':''}</div><button type="button" class="recommend-add" data-add="${p.id}" aria-label="إضافة ${safe(pname(p))}">+</button></article>`).join('')}</div>`:''}
function cartIncentives(anchorId){const q=cartQuote(),nudge=deliveryNudge(q);return `${nudge?`<div class="delivery-goal"><b>اقتربتِ من التوصيل المجاني ♡</b><p>أضيفي منتجات بقيمة ${money(nudge.remainingFils)} أو أكثر ليتجاوز مجموع المنتجات 19 دينارًا ويصبح التوصيل مجانيًا.</p><progress max="19010" value="${q.subtotalFils}" aria-label="تقدم السلة نحو التوصيل المجاني"></progress></div>`:`<p class="shipping-note ${q.shippingFeeFils===0?'shipping-free':''}">${shippingMessage(q.subtotalFils)}</p>`}<h4 class="recommend-title">${nudge?'اختيارات تساعدكِ على إكمال الطلب':'اختيارات تكمّل روتينكِ'}</h4>${suggestionCards(anchorId,!!nudge)}`}
