function addPromotion(id){const offer=state.promotions.map(promotionData).find(p=>p?.id===id);if(!offer)return;const next=state.cart.map(x=>({...x}));for(const item of offer.items){const p=find(item.id),variant=p?activeVariant(p):'',old=next.find(x=>x.id===item.id&&(x.variant||'')===variant),total=next.filter(x=>x.id===item.id).reduce((n,x)=>n+x.qty,0)+item.qty;if(!p||!canBuy(p)||total>Math.min(10,stock(p))){toast('الكمية المتاحة لا تكفي لإضافة هذا العرض كاملًا');return}if(old)old.qty+=item.qty;else next.push({id:item.id,qty:item.qty,variant})}if(next.length>20){toast('يمكن إضافة 20 اختيارًا مختلفًا في الطلب');return}state.cart=next;saveCart();refreshCheckoutSummary();renderDrawer();if(cartSelectionError(state.cart,state.products))toast('اختاري الدرجات أو النسخ المطلوبة من السلة ♡')}
